files.patch:
@@ -65,3 +65,12 @@ div.output_area.stdout {
   .lang-toggle-btn { --lt-border: #30363d; --lt-bg:#161b22; --lt-bg-hover:#1c2128; }
   .lang-toggle-btn .lang-seg { color: #adbac7; }
 }
+
+/* Comfortable article text, with a short categorized library entry point. */
+.bd-article { font-size: 18px; line-height: 1.8; }
+.bd-sidebar-primary { font-size: 16px; }
+.library-categories .toctree-wrapper > ul { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; padding: 0; list-style: none; }
+.library-categories .toctree-l1 { margin: 0; padding: 24px; border: 1px solid var(--pst-color-border); border-radius: 12px; background: var(--pst-color-surface); }
+.library-categories .toctree-l1 > a { font-size: 20px; font-weight: 650; }
+.library-categories .toctree-l1 > ul { display: none; }
+@media (max-width: 600px) { .library-categories .toctree-wrapper > ul { grid-template-columns: minmax(0, 1fr); } }

@@ -0,0 +1,2905 @@
+:root {
+  --paper: #faf9f5;
+  --ink: #202725;
+  --muted: #62706c;
+  --line: #d9ded6;
+  --yellow: #ffda35;
+  --blue: #a3e1ef;
+  --mint: #e5f3e8;
+  --radius: 18px;
+  font-family: Inter, "Arial", "PingFang SC", "Microsoft YaHei", sans-serif;
+  color: var(--ink);
+  background: var(--paper);
+  font-synthesis: none;
+  font-size: 18px;
+  line-height: 1.65;
+  scroll-behavior: smooth
+}
+
+* {
+  box-sizing: border-box
+}
+
+body {
+  margin: 0
+}
+
+button,
+input,
+select {
+  font: inherit
+}
+
+button,
+a,
+input {
+  -webkit-tap-highlight-color: transparent
+}
+
+button,
+a {
+  touch-action: manipulation
+}
+
+button {
+  cursor: pointer;
+  color: inherit
+}
+
+a {
+  color: inherit;
+  text-decoration: none
+}
+
+a:hover {
+  text-decoration: underline;
+  text-underline-offset: 4px
+}
+
+button {
+  border: 1px solid var(--line);
+  background: transparent;
+  border-radius: 8px;
+  padding: 9px 12px;
+  font-size: 15px;
+  font-weight: 600
+}
+
+button:hover:not(:disabled) {
+  background: #e8ece5
+}
+
+button:disabled {
+  cursor: default;
+  opacity: .42
+}
+
+button:focus-visible,
+a:focus-visible,
+input:focus-visible,
+select:focus-visible,
+[tabindex]:focus-visible {
+  outline: 3px solid #187991;
+  outline-offset: 4px
+}
+
+button,
+input,
+a {
+  transition: background .18s, border-color .18s, transform .18s
+}
+
+button:active:not(:disabled) {
+  transform: translateY(2px)
+}
+
+[hidden] {
+  display: none !important
+}
+
+.skip-link {
+  position: fixed;
+  top: -70px;
+  left: 20px;
+  z-index: 30;
+  background: var(--yellow);
+  padding: 16px
+}
+
+.skip-link:focus {
+  top: 12px
+}
+
+.site-header {
+  height: 88px;
+  max-width: 1400px;
+  margin: auto;
+  padding: 0 48px;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  border-bottom: 1px solid var(--line)
+}
+
+.brand {
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  font-size: 28px;
+  font-weight: 850;
+  letter-spacing: -1.3px
+}
+
+.brand img {
+  border-radius: 50%;
+  border: 1px solid var(--ink)
+}
+
+.brand span {
+  font-size: 15px;
+  font-weight: 400;
+  letter-spacing: 0;
+  color: var(--muted)
+}
+
+.site-header nav {
+  display: flex;
+  gap: 25px;
+  align-items: center;
+  font-size: 15px;
+  font-weight: 600
+}
+
+.lang-toggle-btn {
+  border: 0;
+  padding: 8px 0
+}
+
+.lang-seg {
+  opacity: .4
+}
+
+.lang-toggle-btn[data-current=en] [data-lang=en],
+.lang-toggle-btn[data-current=zh] [data-lang=zh] {
+  opacity: 1
+}
+
+.lang-sep {
+  padding: 0 4px;
+  color: var(--line)
+}
+
+main {
+  max-width: 1400px;
+  margin: auto;
+  padding: 0 48px
+}
+
+.hero {
+  display: grid;
+  grid-template-columns: 1.45fr 1fr;
+  align-items: center;
+  gap: 40px;
+  padding: 80px 0 70px;
+  min-height: 440px
+}
+
+.eyebrow {
+  font-family: "Courier New", monospace;
+  font-size: 14px;
+  font-weight: 700;
+  letter-spacing: 1.5px;
+  line-height: 1.6;
+  display: flex;
+  align-items: center;
+  gap: 9px
+}
+
+.live-dot {
+  width: 7px;
+  height: 7px;
+  border-radius: 50%;
+  background: #459c6b;
+  box-shadow: 0 0 0 4px #e1eedf
+}
+
+h1 {
+  font-size: clamp(40px, 4.1vw, 60px);
+  letter-spacing: -2.6px;
+  line-height: 1.12;
+  margin: 26px 0 22px;
+  font-weight: 800
+}
+
+h1 span {
+  color: #417b88
+}
+
+html[lang=zh-CN] h1 {
+  font-size: clamp(36px, 3.4vw, 50px);
+  line-height: 1.35;
+  letter-spacing: -1.8px
+}
+
+.hero-description {
+  font-size: 18px;
+  line-height: 1.9;
+  color: var(--muted);
+  max-width: 525px;
+  margin: 0 0 25px
+}
+
+.button {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 24px;
+  border-radius: 9px;
+  padding: 13px 19px;
+  font-size: 15px;
+  font-weight: 700;
+  border: 1px solid var(--ink);
+  text-decoration: none !important
+}
+
+.primary {
+  background: var(--yellow);
+  box-shadow: 2px 3px 0 var(--ink)
+}
+
+.primary:hover:not(:disabled) {
+  background: #f4cd15;
+  transform: translateY(-2px)
+}
+
+.dark {
+  background: var(--ink);
+  color: white
+}
+
+.dark:hover:not(:disabled) {
+  background: #36433d
+}
+
+.light {
+  background: var(--paper)
+}
+
+.hero-note {
+  font-size: 14px;
+  color: var(--muted);
+  display: inline-block;
+  margin-left: 14px
+}
+
+.hero-art {
+  justify-self: center;
+  position: relative;
+  width: 330px;
+  height: 330px;
+  display: flex;
+  align-items: center;
+  justify-content: center
+}
+
+.mascot-frame {
+  width: 268px;
+  height: 268px;
+  border-radius: 38% 55% 40% 46%;
+  background: var(--yellow);
+  overflow: hidden;
+  border: 2px solid var(--ink);
+  transform: rotate(-8deg);
+  box-shadow: 10px 12px 0 #cbe9e8
+}
+
+.mascot-frame img {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+  transform: rotate(8deg) scale(1.03)
+}
+
+.orbit-label {
+  position: absolute;
+  background: white;
+  padding: 9px 13px;
+  border: 1px solid var(--ink);
+  border-radius: 6px;
+  font-family: monospace;
+  font-size: 14px;
+  z-index: 1;
+  box-shadow: 2px 3px 0 #d9ded6
+}
+
+.label-top {
+  top: 14px;
+  left: -15px;
+  transform: rotate(-5deg)
+}
+
+.label-bottom {
+  bottom: 6px;
+  right: -8px;
+  transform: rotate(4deg)
+}
+
+.spark {
+  position: absolute;
+  font-size: 38px
+}
+
+.spark-one {
+  right: -12px;
+  top: 38px;
+  color: #3988a0
+}
+
+.spark-two {
+  bottom: 34px;
+  left: -14px;
+  font-size: 29px
+}
+
+.lab {
+  border-top: 1px solid var(--line);
+  padding: 38px 0 60px;
+  scroll-margin-top: 20px
+}
+
+.lab-heading,
+.recipe-heading {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 16px
+}
+
+h2 {
+  font-size: 30px;
+  letter-spacing: -1px;
+  margin: 8px 0 12px;
+  line-height: 1.35
+}
+
+.lab-heading .eyebrow {
+  color: var(--muted)
+}
+
+.history-actions {
+  display: flex;
+  gap: 8px
+}
+
+.history-actions button {
+  font-size: 14px
+}
+
+.presets {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  margin: 18px 0 28px;
+  flex-wrap: wrap
+}
+
+.presets>span {
+  font-size: 14px;
+  color: var(--muted);
+  margin-right: 6px
+}
+
+.presets button {
+  border-radius: 24px;
+  background: white;
+  font-weight: 400;
+  font-size: 14px
+}
+
+.presets button:hover {
+  border-color: var(--ink)
+}
+
+.steps {
+  display: grid;
+  grid-template-columns: repeat(6, 1fr);
+  gap: 4px;
+  margin-bottom: 18px
+}
+
+.steps button {
+  padding: 14px 5px;
+  border: 0;
+  border-radius: 8px;
+  color: var(--muted);
+  text-align: left;
+  border-bottom: 2px solid var(--line);
+  font-size: 14px
+}
+
+.steps button span {
+  font-family: monospace;
+  font-size: 14px;
+  margin-right: 8px;
+  opacity: .75
+}
+
+.steps button[aria-current=step] {
+  color: var(--ink);
+  border-bottom-color: var(--ink);
+  background: #f0efdf
+}
+
+.workbench {
+  display: grid;
+  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);
+  gap: 20px;
+  align-items: start
+}
+
+.builder-panel {
+  background: white;
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  padding: 27px;
+  min-height: 585px;
+  display: flex;
+  flex-direction: column
+}
+
+.step-heading {
+  display: flex;
+  gap: 15px;
+  align-items: flex-start;
+  margin-bottom: 23px
+}
+
+.step-number {
+  font-family: monospace;
+  background: var(--yellow);
+  padding: 8px 9px;
+  border: 1px solid var(--ink);
+  border-radius: 9px;
+  font-size: 18px
+}
+
+.step-heading h3 {
+  font-size: 21px;
+  margin: 2px 0 7px;
+  letter-spacing: -.5px
+}
+
+.step-heading p {
+  font-size: 15px;
+  line-height: 1.7;
+  color: var(--muted);
+  margin: 0
+}
+
+.field-group {
+  border: 0;
+  margin: 0 0 20px;
+  padding: 0;
+  min-width: 0
+}
+
+.field-group legend,
+.input-label {
+  font-size: 14px;
+  font-weight: 700;
+  margin-bottom: 9px
+}
+
+.option-grid {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 9px
+}
+
+.option-card {
+  position: relative;
+  display: flex;
+  flex-direction: column;
+  text-align: left;
+  background: var(--paper);
+  border: 1px solid var(--line);
+  border-radius: 10px;
+  padding: 13px 14px;
+  cursor: pointer;
+  transition: background .2s, border-color .2s, transform .2s
+}
+
+.option-card:hover {
+  border-color: #839790;
+  transform: translateY(-2px)
+}
+
+.option-card:has(input:checked) {
+  background: #e8f5f3;
+  border-color: #397d78;
+  box-shadow: inset 0 0 0 1px #397d78
+}
+
+.option-card input {
+  position: absolute;
+  right: 11px;
+  top: 13px;
+  width: 14px;
+  height: 14px;
+  accent-color: #337a73;
+  margin: 0
+}
+
+.option-title {
+  font-size: 15px;
+  font-weight: 700;
+  padding-right: 17px;
+  line-height: 1.4
+}
+
+.option-description {
+  font-size: 14px;
+  line-height: 1.65;
+  color: var(--muted);
+  margin-top: 5px
+}
+
+.option-grid.single {
+  grid-template-columns: 1fr
+}
+
+.toggle-row {
+  display: flex;
+  align-items: flex-start;
+  gap: 11px;
+  padding: 13px 0;
+  border-bottom: 1px solid #e8ece5;
+  cursor: pointer
+}
+
+.toggle-row input {
+  accent-color: #397d78;
+  width: 17px;
+  height: 17px;
+  margin: 1px 0 0;
+  flex-shrink: 0
+}
+
+.toggle-row strong {
+  display: block;
+  font-size: 15px
+}
+
+.toggle-row small {
+  display: block;
+  color: var(--muted);
+  font-size: 14px;
+  line-height: 1.6;
+  margin-top: 5px
+}
+
+.inputs-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 13px;
+  margin: 12px 0
+}
+
+.input-label {
+  display: block;
+  line-height: 1.5
+}
+
+.input-label input,
+.input-label select {
+  width: 100%;
+  border: 1px solid var(--line);
+  border-radius: 7px;
+  padding: 10px;
+  font-size: 14px;
+  background: var(--paper);
+  margin-top: 6px;
+  color: var(--ink);
+  min-width: 0
+}
+
+.input-label.wide {
+  grid-column: 1/-1
+}
+
+.input-label small {
+  font-size: 14px;
+  font-weight: 400;
+  color: var(--muted);
+  display: block;
+  margin-top: 5px
+}
+
+.step-help {
+  display: flex;
+  gap: 6px;
+  flex-wrap: wrap;
+  margin: 8px 0 20px
+}
+
+.learn-button {
+  border: 0;
+  padding: 6px 7px;
+  font-size: 14px;
+  color: #326f83;
+  background: #edf5f7
+}
+
+.step-controls {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  gap: 10px;
+  border-top: 1px solid var(--line);
+  padding-top: 18px;
+  margin-top: auto
+}
+
+.step-controls>span {
+  font-size: 14px;
+  color: var(--muted)
+}
+
+.preview {
+  border: 1px solid #c9d9d5;
+  border-radius: var(--radius);
+  overflow: hidden;
+  background: #edf3ee;
+  position: sticky;
+  top: 18px
+}
+
+.preview-heading {
+  padding: 18px 19px 0;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 8px
+}
+
+.preview-heading .eyebrow {
+  font-size: 14px;
+  letter-spacing: 1px
+}
+
+.preview-heading button {
+  font-size: 14px;
+  border-color: #bacdc4;
+  padding: 7px 9px;
+  background: #fff9
+}
+
+.world {
+  min-height: 252px;
+  padding: 23px 24px 10px;
+  background-image: radial-gradient(#bdcec7 .7px, transparent .7px);
+  background-size: 14px 14px;
+  position: relative
+}
+
+.world-top {
+  font-size: 14px;
+  font-family: monospace;
+  text-align: center;
+  letter-spacing: 1px;
+  color: var(--muted);
+  margin-bottom: 18px
+}
+
+.world-nodes {
+  display: grid;
+  grid-template-columns: 1fr 36px 1fr;
+  align-items: center;
+  gap: 3px
+}
+
+.world-node {
+  background: #fffdf7;
+  border: 1.5px solid #35413a;
+  border-radius: 13px;
+  padding: 14px 10px;
+  text-align: center;
+  box-shadow: 3px 4px 0 #bdcfc5;
+  transition: all .35s;
+  min-width: 0;
+  position: relative
+}
+
+.world-node strong {
+  display: block;
+  font-size: 15px;
+  line-height: 1.5
+}
+
+.world-node small {
+  display: block;
+  font-size: 14px;
+  color: var(--muted);
+  margin-top: 4px
+}
+
+.world-node.trainer {
+  background: #ffeb87
+}
+
+.world-node.sampler {
+  background: #bdeaf1
+}
+
+.world-node.external {
+  border-style: dashed;
+  box-shadow: 4px 4px 0 #bdcfd6
+}
+
+.chips {
+  display: flex;
+  gap: 3px;
+  margin: 10px auto 0;
+  justify-content: center;
+  flex-wrap: wrap;
+  max-width: 135px
+}
+
+.gpu {
+  display: block;
+  width: 14px;
+  height: 17px;
+  border: 1px solid #64736d;
+  border-radius: 3px;
+  background: #fff8;
+  position: relative
+}
+
+.gpu:after {
+  content: '';
+  position: absolute;
+  inset: 4px 3px;
+  background: #9aa9a0;
+  border-radius: 1px
+}
+
+.flow-arrow {
+  text-align: center;
+  position: relative;
+  color: #61796c;
+  font-size: 22px
+}
+
+.flow-arrow:after {
+  content: '';
+  position: absolute;
+  left: 5px;
+  top: 7px;
+  width: 7px;
+  height: 7px;
+  background: #318994;
+  border-radius: 50%;
+  opacity: 0
+}
+
+.world.running .flow-arrow:after {
+  animation: flow 1.5s infinite
+}
+
+.world.running .world-node.active {
+  box-shadow: 0 0 0 5px #8ebea055, 3px 4px 0 #bdcfc5;
+  transform: translateY(-4px)
+}
+
+.world-colocate {
+  border: 1px dashed #94a59d;
+  padding: 16px 10px 10px;
+  border-radius: 15px;
+  position: relative
+}
+
+.pool-label {
+  display: block;
+  font-size: 14px;
+  color: #5f7669;
+  text-align: center;
+  margin-top: 12px;
+  font-family: monospace
+}
+
+.reward-loop {
+  border: 1px solid #a0b7ac;
+  border-top: 0;
+  border-radius: 0 0 14px 14px;
+  width: 72%;
+  height: 27px;
+  margin: auto;
+  position: relative
+}
+
+.reward-loop span {
+  position: absolute;
+  bottom: -9px;
+  left: 50%;
+  transform: translateX(-50%);
+  font-size: 14px;
+  background: #edf3ee;
+  padding: 0 8px;
+  white-space: nowrap
+}
+
+.pd-nodes {
+  display: flex;
+  gap: 4px;
+  margin-top: 9px
+}
+
+.pd-nodes span {
+  border: 1px solid #60929b;
+  padding: 4px;
+  border-radius: 5px;
+  font-size: 14px;
+  flex: 1;
+  background: #dff6fa
+}
+
+.cache-tier {
+  font-size: 14px;
+  border: 1px dashed #698b96;
+  background: #f7f2dc;
+  border-radius: 5px;
+  margin: 7px 0 0;
+  padding: 4px
+}
+
+.simulation-status {
+  min-height: 29px;
+  text-align: center;
+  font-size: 14px;
+  color: var(--muted);
+  padding: 0 16px;
+  margin: 8px 0 12px;
+  line-height: 1.5
+}
+
+.summary {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  padding: 15px 20px;
+  background: #fff9;
+  border-top: 1px solid #d1ddd6;
+  border-bottom: 1px solid #d1ddd6;
+  gap: 8px
+}
+
+.summary small {
+  display: block;
+  font-size: 14px;
+  color: var(--muted);
+  margin-bottom: 6px
+}
+
+.summary strong {
+  font-size: 14px;
+  font-weight: 650
+}
+
+.advice {
+  padding: 15px 20px;
+  font-size: 14px;
+  line-height: 1.75
+}
+
+.advice p {
+  margin: 0 0 8px
+}
+
+.advice p:last-child {
+  margin: 0
+}
+
+.advice .warning {
+  color: #825c20
+}
+
+.review-link {
+  display: flex;
+  justify-content: space-between;
+  padding: 14px 20px;
+  border-top: 1px solid #d1ddd6;
+  font-size: 14px;
+  font-weight: 700
+}
+
+.recipe {
+  background: var(--ink);
+  color: #f9f9ef;
+  padding: 34px;
+  border-radius: 20px;
+  margin: 0 0 60px;
+  scroll-margin-top: 20px
+}
+
+.recipe-heading h2 {
+  margin-bottom: 7px
+}
+
+.recipe-heading p:not(.eyebrow) {
+  font-size: 14px;
+  color: #afc0b5;
+  line-height: 1.7
+}
+
+.recipe-heading .button {
+  color: var(--ink);
+  white-space: nowrap
+}
+
+.recipe .eyebrow {
+  color: #cde398
+}
+
+.artifact-toolbar {
+  margin-top: 25px;
+  background: #303b35;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+  border-radius: 9px 9px 0 0;
+  padding: 10px 13px;
+  flex-wrap: wrap
+}
+
+.artifact-tabs {
+  display: flex;
+  gap: 8px;
+  flex-wrap: wrap
+}
+
+.artifact-tabs button {
+  color: #c2cfc5;
+  border: 0;
+  font-family: monospace;
