+    const status = document.createElement('p');
+    status.setAttribute('role', 'status');
+    status.textContent = zh ? '正在加载完整说明与推导…' : 'Loading the full guide and derivation…';
+    content.appendChild(status);
+    dialog.scrollTop = 0;
